import sys

data = sys.stdin.read().split()
n, x, y = int(data[0]), int(data[1]), int(data[2])
M = [[int(ch) for ch in data[3 + i]] for i in range(n)]
INF = 10**9
d = [[INF] * n for _ in range(n)]
for i in range(n):
    d[i][i] = 0
    for j in range(n):
        if M[i][j] == 1 and i != j:
            d[i][j] = 1
for k in range(n):
    for i in range(n):
        for j in range(n):
            if d[i][k] + d[k][j] < d[i][j]:
                d[i][j] = d[i][k] + d[k][j]
print(d[x][y] if d[x][y] < INF else -1)

